import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * TIER-07: what `contract/openapi.json` (generated by `npm run contract:build`)
 * says about the tier badge, which is what the app's types are generated from.
 *
 * - `badge` can be null, so it must be written the OpenAPI 3.0 way that keeps
 *   the null (`{ allOf: [{ $ref }], nullable: true }`); a `nullable` beside a
 *   bare `$ref` is ignored and the app would be told it is never null.
 * - The number on the badge is a whole number that can be null.
 * - The views the web reads gain no `badge` key.
 */

type Schema = {
  $ref?: string;
  allOf?: Schema[];
  nullable?: boolean;
  type?: string;
  properties?: Record<string, Schema>;
  required?: string[];
};
const contract = JSON.parse(
  readFileSync(join(__dirname, '../../../../contract/openapi.json'), 'utf8'),
) as { components: { schemas: Record<string, Schema> } };
const schemas = contract.components.schemas;

describe('the tier badge in the contract (TIER-07)', () => {
  it('PersonBadgeView is the plan badge plus its name and number, the number a whole number or null', () => {
    const p = schemas.PersonBadgeView.properties!;
    expect(Object.keys(p).sort()).toEqual(['id', 'name', 'number', 'numbered']);
    expect(p.number).toEqual({ type: 'integer', nullable: true });
    expect(schemas.PersonBadgeView.required!.sort()).toEqual([
      'id',
      'name',
      'number',
      'numbered',
    ]);
  });

  it.each([
    'ProfileFieldsView',
    'CreatorCard',
    'ProfessionalCard',
    'ExploreCreatorCard',
    'ProfessionalDirectoryEntry',
    'ProfessionalDirectoryProfile',
  ])('%s.badge may be null in the contract and is always present', (owner) => {
    const s = schemas[owner].properties?.badge;
    expect(s?.nullable).toBe(true);
    expect(s?.$ref).toBeUndefined();
    expect(s?.allOf).toEqual([
      { $ref: '#/components/schemas/PersonBadgeView' },
    ]);
    expect(schemas[owner].required).toContain('badge');
  });

  it.each([
    'CreatorProfile',
    'UserProfileWithClaims',
    'ProfessionalListItem',
    'MyTierView',
  ])('%s, which the web or TIER-01 pins, has no badge key', (owner) => {
    expect(schemas[owner].properties).not.toHaveProperty('badge');
  });
});
